module serial2parallel (
	input clk, rst_n, din_valid, din_serial,
	output reg dout_valid,
	reg [3:0] cnt,
	output reg [7:0] dout_parallel
);

// TODO: Please add your logic design here

    always@(posedge clk) begin
        if(!rst_n) begin
			cnt <= 4'd0;
		end
        else if(cnt==4'd8) 
			cnt <= 4'd0;
		else if(din_valid) 
			cnt <= cnt + 4'd1;
		else 
			cnt <= cnt;
    end

    always@(*) begin
		if(cnt==4'd8) 
			dout_parallel[cnt-4'd1] = din_serial;
		else 
			dout_parallel[cnt] = din_serial;
	end

	always@(*) begin
		if(cnt!=4'd8)
			dout_valid = 1'd0;
		else 
			dout_valid = 1'd1;
	end
endmodule
